-- ISSUE-PROBE-AGENT-1 (2026-10-26): every open issue gets a live defect check, written by the fleet's Cloudflare agent.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE fleet_crons SET enabled = 0 WHERE name = 'issue-probe-agent-hourly'; UPDATE fleet_tasks SET enabled = 0 WHERE id = 'issue-probe-agent'; UPDATE ops_config SET value = 'off' WHERE key = 'issue_probe_agent';
--
-- Why: on 2026-10-26 133 open issues had no active, monitoring or holding remediation contract (most carried a superseded birth
-- contract that only re-read the issue's own status), so the hourly remediation tick could never close them and they fed
-- open_agent_issues, issues_open_over_120m and the issue-backlog breach cause.
-- How: an hourly fleet workflow (fleet_crons '50 * * * *') queues up to ops_config issue_probe_agent_per_hour such issues in
-- cf_agent_requests (requester issue-probe-agent). qnfo-agents runs each turn with read-only fleet_sql, so the agent reads the data
-- and runs its check before answering with JSON. The next run parses the answer and, when the check is one read-only SELECT with
-- expected and observed columns that does not read the issue's own status, writes it as the issue's d1-query contract. The hourly
-- remediation tick then closes the issue with evidence when the defect is gone; recurrence_guard reopens it if the check fails later.
-- An issue is asked again after 24 hours when no check was applied. issue_probe_requests is the ledger of every attempt.

CREATE TABLE IF NOT EXISTS issue_probe_requests (
  issue_id INTEGER PRIMARY KEY,
  request_id INTEGER,
  requested_at TEXT,
  answered_at TEXT,
  verdict TEXT,
  probe TEXT,
  applied_at TEXT,
  note TEXT
);
INSERT OR IGNORE INTO ops_config (key, value, note) VALUES ('issue_probe_agent', 'on', 'ISSUE-PROBE-AGENT-1: off stops new agent requests and stops applying their checks'),
  ('issue_probe_agent_per_hour', '12', 'ISSUE-PROBE-AGENT-1: issues sent to the agent per hourly run');
INSERT OR REPLACE INTO fleet_tasks (id, name, type, definition, timeout_ms, retries, version, enabled, updated_at)
VALUES ('issue-probe-agent', 'ISSUE-PROBE-AGENT-1: the fleet agent writes a live defect check for every open issue that has none, so it closes when fixed', 'workflow',
  '{"steps": [{"type": "sql", "name": "probe-request", "db": "AUDIT", "sql": "INSERT INTO cf_agent_requests (requester, kind, prompt, instance, priority) SELECT ''issue-probe-agent'', ''run'', ''Issue #'' || a.id || '' in the QNFO fleet is open, but nothing checks whether it is fixed, so it never closes on its own.'' || char(10) || ''Title: '' || a.title || char(10) || ''Description: '' || substr(COALESCE(a.description, ''''), 1, 2500) || char(10) || char(10) || ''Write one read-only SQL check on the D1 database qnfo-audit that tells whether this defect is still present. Use fleet_sql to read the tables involved and to run your check before you answer. Rules: one SELECT or WITH statement, no semicolon, returning one row with two text columns named expected and observed. observed must equal expected only when the defect is gone and must differ while it is present. Measure the defect itself (rows, counts, ages, ledger events, metric_registry values), never the status of this issue or of its triage, contract or verification rows. If the defect is already gone, the check must show that from the data. Answer with only a JSON object and nothing else: {\"verdict\":\"probe\",\"probe\":\"SELECT ...\",\"observed_now\":\"what your run returned\",\"why\":\"one sentence\"}. If the defect cannot be measured in qnfo-audit, answer {\"verdict\":\"none\",\"why\":\"one sentence\"}.'', ''probe-issue-'' || a.id, ''medium'' FROM agent_issues a LEFT JOIN remediation_contracts c ON c.class = ''issue-'' || a.id WHERE a.status = ''open'' AND COALESCE(c.status, ''none'') NOT IN (''active'', ''monitoring'', ''holding'') AND a.created_at < CAST(strftime(''%s'', ''now'', ''-120 minutes'') AS INTEGER) * 1000 AND a.title NOT LIKE ''PROBE-NEEDED-1%'' AND a.title NOT LIKE ''ROOT-CAUSE-1%'' AND a.title NOT LIKE ''TOOL-FAILURE:%'' AND a.title NOT LIKE ''SELF-AUDIT-TOOLERR:%'' AND a.title NOT LIKE ''[self-heal] tool %'' AND NOT EXISTS (SELECT 1 FROM issue_probe_requests q WHERE q.issue_id = a.id AND q.requested_at > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-24 hours'')) AND COALESCE((SELECT value FROM ops_config WHERE key = ''issue_probe_agent''), ''on'') <> ''off'' ORDER BY CASE a.priority WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 WHEN ''low'' THEN 3 ELSE 4 END, a.id LIMIT CAST(COALESCE((SELECT value FROM ops_config WHERE key = ''issue_probe_agent_per_hour''), ''12'') AS INTEGER)"}, {"type": "sql", "name": "probe-record", "db": "AUDIT", "sql": "INSERT OR REPLACE INTO issue_probe_requests (issue_id, request_id, requested_at) SELECT CAST(substr(r.instance, 13) AS INTEGER), r.id, r.created_at FROM cf_agent_requests r WHERE r.requester = ''issue-probe-agent'' AND r.instance LIKE ''probe-issue-%'' AND NOT EXISTS (SELECT 1 FROM issue_probe_requests q WHERE q.issue_id = CAST(substr(r.instance, 13) AS INTEGER) AND q.request_id >= r.id)"}, {"type": "sql", "name": "probe-parse", "db": "AUDIT", "sql": "UPDATE issue_probe_requests SET answered_at = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now''), verdict = (SELECT CASE WHEN json_valid(substr(rtrim(r.result, char(96, 10, 13, 32)), instr(r.result, ''{''))) THEN COALESCE(json_extract(substr(rtrim(r.result, char(96, 10, 13, 32)), instr(r.result, ''{'')), ''$.verdict''), ''unparsed'') ELSE ''unparsed'' END FROM cf_agent_requests r WHERE r.id = issue_probe_requests.request_id), probe = (SELECT CASE WHEN json_valid(substr(rtrim(r.result, char(96, 10, 13, 32)), instr(r.result, ''{''))) THEN json_extract(substr(rtrim(r.result, char(96, 10, 13, 32)), instr(r.result, ''{'')), ''$.probe'') END FROM cf_agent_requests r WHERE r.id = issue_probe_requests.request_id), note = (SELECT substr(COALESCE(CASE WHEN json_valid(substr(rtrim(r.result, char(96, 10, 13, 32)), instr(r.result, ''{''))) THEN json_extract(substr(rtrim(r.result, char(96, 10, 13, 32)), instr(r.result, ''{'')), ''$.why'') || '' (observed now: '' || COALESCE(json_extract(substr(rtrim(r.result, char(96, 10, 13, 32)), instr(r.result, ''{'')), ''$.observed_now''), ''?'') || '')'' END, r.error, r.result), 1, 600) FROM cf_agent_requests r WHERE r.id = issue_probe_requests.request_id) WHERE answered_at IS NULL AND request_id IN (SELECT id FROM cf_agent_requests WHERE status IN (''done'', ''failed'', ''error''))"}, {"type": "sql", "name": "probe-reject", "db": "AUDIT", "sql": "UPDATE issue_probe_requests SET verdict = ''rejected'', note = substr(''ISSUE-PROBE-AGENT-1 refused the check (not one read-only SELECT with expected and observed, or it reads the issue''''s own status): '' || COALESCE(note, ''''), 1, 600) WHERE issue_id IN (SELECT p.issue_id FROM issue_probe_requests p WHERE p.verdict = ''probe'' AND p.applied_at IS NULL AND NOT (p.probe IS NOT NULL AND length(p.probe) BETWEEN 30 AND 4000 AND (lower(trim(p.probe)) LIKE ''select%'' OR lower(trim(p.probe)) LIKE ''with%'') AND instr(rtrim(trim(p.probe), char(59)), char(59)) = 0 AND instr(lower(p.probe), ''expected'') > 0 AND instr(lower(p.probe), ''observed'') > 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''insert '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''update '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''delete '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''drop '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''alter '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''create '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''attach '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''detach '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''pragma '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''replace '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''vacuum'') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''reindex'') = 0 AND NOT (instr(lower(p.probe), ''agent_issues'') > 0 AND instr(p.probe, CAST(p.issue_id AS TEXT)) > 0) AND instr(lower(p.probe), ''issue_triage'') = 0 AND instr(lower(p.probe), ''remediation_contracts'') = 0 AND instr(lower(p.probe), ''remediation_verifications'') = 0))"}, {"type": "sql", "name": "probe-contract-row", "db": "AUDIT", "sql": "INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status) SELECT ''issue-'' || p.issue_id, p.issue_id, ''ISSUE-PROBE-AGENT-1'', ''close the issue when the defect check passes'', p.probe, ''d1-query'', 3, ''qnfo-fleet-control'', 1, ''active'' FROM issue_probe_requests p JOIN agent_issues a ON a.id = p.issue_id WHERE a.status = ''open'' AND p.verdict = ''probe'' AND p.applied_at IS NULL AND (p.probe IS NOT NULL AND length(p.probe) BETWEEN 30 AND 4000 AND (lower(trim(p.probe)) LIKE ''select%'' OR lower(trim(p.probe)) LIKE ''with%'') AND instr(rtrim(trim(p.probe), char(59)), char(59)) = 0 AND instr(lower(p.probe), ''expected'') > 0 AND instr(lower(p.probe), ''observed'') > 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''insert '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''update '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''delete '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''drop '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''alter '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''create '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''attach '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''detach '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''pragma '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''replace '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''vacuum'') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''reindex'') = 0 AND NOT (instr(lower(p.probe), ''agent_issues'') > 0 AND instr(p.probe, CAST(p.issue_id AS TEXT)) > 0) AND instr(lower(p.probe), ''issue_triage'') = 0 AND instr(lower(p.probe), ''remediation_contracts'') = 0 AND instr(lower(p.probe), ''remediation_verifications'') = 0)"}, {"type": "sql", "name": "probe-apply", "db": "AUDIT", "sql": "UPDATE remediation_contracts SET verify_probe = (SELECT p.probe FROM issue_probe_requests p WHERE ''issue-'' || p.issue_id = remediation_contracts.class), verify_transport = ''d1-query'', status = ''active'', precondition = ''ISSUE-PROBE-AGENT-1'', attempts = 0, next_due_at = NULL, last_verdict = ''ISSUE-PROBE-AGENT-1: defect check written by the fleet agent (cf_agent_requests #'' || (SELECT p.request_id FROM issue_probe_requests p WHERE ''issue-'' || p.issue_id = remediation_contracts.class) || '')'' WHERE class IN (SELECT ''issue-'' || p.issue_id FROM issue_probe_requests p JOIN agent_issues a ON a.id = p.issue_id WHERE a.status = ''open'' AND p.verdict = ''probe'' AND p.applied_at IS NULL AND (p.probe IS NOT NULL AND length(p.probe) BETWEEN 30 AND 4000 AND (lower(trim(p.probe)) LIKE ''select%'' OR lower(trim(p.probe)) LIKE ''with%'') AND instr(rtrim(trim(p.probe), char(59)), char(59)) = 0 AND instr(lower(p.probe), ''expected'') > 0 AND instr(lower(p.probe), ''observed'') > 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''insert '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''update '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''delete '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''drop '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''alter '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''create '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''attach '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''detach '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''pragma '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''replace '') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''vacuum'') = 0 AND instr(lower('' '' || replace(replace(p.probe, char(10), '' ''), char(13), '' '') || '' ''), ''reindex'') = 0 AND NOT (instr(lower(p.probe), ''agent_issues'') > 0 AND instr(p.probe, CAST(p.issue_id AS TEXT)) > 0) AND instr(lower(p.probe), ''issue_triage'') = 0 AND instr(lower(p.probe), ''remediation_contracts'') = 0 AND instr(lower(p.probe), ''remediation_verifications'') = 0))"}, {"type": "sql", "name": "probe-mark", "db": "AUDIT", "sql": "UPDATE issue_probe_requests SET applied_at = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'') WHERE verdict = ''probe'' AND applied_at IS NULL AND EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.class = ''issue-'' || issue_probe_requests.issue_id AND c.precondition = ''ISSUE-PROBE-AGENT-1'' AND c.verify_probe = issue_probe_requests.probe)"}]}', 60000, 1, 1, 1, strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR REPLACE INTO fleet_crons (name, cron_expr, task_id, enabled, timezone, updated_at)
VALUES ('issue-probe-agent-hourly', '50 * * * *', 'issue-probe-agent', 1, 'UTC', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, trigger_condition, symptom, blast_radius)
VALUES ('issue-without-defect-check', 'An open issue has no remediation contract that measures its defect, so it never closes on its own',
  'Birth contracts were superseded or only re-read the issue status; loops and sessions filed issues without a runtime-probe or code-probe line',
  'ISSUE-PROBE-AGENT-1: the fleet agent writes a read-only defect check for each such issue every hour (migrations/2026-10-26-issue-probe-agent.sql)',
  'issues_unprobed_60m', 'issue-probe-agent', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'),
  'open issue older than 120 minutes with no active, monitoring or holding contract', 'open_agent_issues and issues_open_over_120m stay in breach', 'every issue family without a probe line');
INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, surfaces_tested)
SELECT 'session_01RdDA76KLvqYHYBjL9C2be5', 'A check written by the agent against live data, with a false close reopened by recurrence_guard, is better than issues that never close (owner directive 2026-10-26 08:53, relayed)',
  'ISSUE-PROBE-AGENT-1: hourly workflow asks qnfo-agents for a defect check per unchecked open issue and applies valid ones as d1-query contracts',
  '133 open issues without an active contract on 2026-10-26 08:50', 'workflow and cron registered', 'remediation contracts of open issues only; read-only probes',
  'ops_config issue_probe_agent = off; fleet_crons issue-probe-agent-hourly enabled = 0',
  'the fleet writes closing checks for its own issues', 'issues_unprobed_60m <= 10 within 24 h', 'fleet_sql read-only tool, remediation tick d1-query transport, recurrence_guard'
WHERE NOT EXISTS (SELECT 1 FROM decision_log WHERE action LIKE 'ISSUE-PROBE-AGENT-1:%');
